globalThis.show = function show(v) {
  if (typeof v === 'function') return '[function ' + JSON.stringify(v.name) + ' len=' + v.length + ']';
  if (typeof v === 'string') return JSON.stringify(v);
  if (typeof v === 'bigint') return v + 'n';
  if (typeof v === 'symbol') return 'Symbol';
  if (v === undefined) return 'undefined';
  if (v === null) return 'null';
  if (typeof v === 'number') { if (Object.is(v, -0)) return '-0'; return String(v); }
  if (typeof v === 'boolean') return String(v);
  if (typeof Buffer !== 'undefined' && Buffer.isBuffer(v)) return 'Buffer<' + v.toString('hex') + '>(len=' + v.length + ')';
  if (ArrayBuffer.isView(v)) return v.constructor.name + '<len=' + v.length + '>';
  if (v instanceof Error) return errStr(v);
  try { return JSON.stringify(v); } catch (e) { return '[unserializable ' + Object.prototype.toString.call(v) + ']'; }
};
globalThis.errStr = function errStr(e) {
  if (!(e instanceof Object)) return 'THROWN NON-OBJECT: ' + typeof e + ' ' + JSON.stringify(e);
  const ctor = e.constructor ? e.constructor.name : '?';
  const keys = Object.keys(e);
  const own = Object.getOwnPropertyNames(e);
  let extra = {};
  for (const k of own) { if (k !== 'stack' && k !== 'message') { try { extra[k] = e[k]; } catch (x) {} } }
  return 'ERR ctor=' + ctor + ' name=' + JSON.stringify(e.name) + ' message=' + JSON.stringify(e.message) + ' code=' + JSON.stringify(e.code) + ' errno=' + JSON.stringify(e.errno) + ' keys=' + JSON.stringify(keys) + ' own=' + JSON.stringify(own) + ' extra=' + JSON.stringify(extra);
};
globalThis.tryit = function tryit(label, fn) {
  try { const r = fn(); console.log(label + ' => ' + show(r)); return r; } catch (e) { console.log(label + ' THREW ' + errStr(e)); }
};
EOF
